// Some portions generated by Claude
import { computeGraphLayout, type LayoutOptions } from "./graph-layout-engine.ts";
import type { Graph } from "./graph-types.ts";

self.onmessage = async (event: MessageEvent<{ graph: Graph; options: LayoutOptions }>) => {
  try {
    self.postMessage({ result: await computeGraphLayout(event.data.graph, event.data.options) });
  } catch (error) {
    self.postMessage({ error: error instanceof Error ? error.message : String(error) });
  }
};
